import { describe, expect, it } from 'vitest';
import {
  CanonicalFloat,
  CanonicalizationError,
  canonicalBytes,
  canonicalHash,
  decimalText,
  hashMultifileManifest,
  type CanonicalValue,
  type ManifestFile,
} from '../src/index';
import fixtureJson from './fixtures/amc-canon-1.json';

// Generated by services/langgraph/tests/test_canonical_parity_fixture.py (Python is the reference).
interface FixtureCase {
  readonly name: string;
  readonly input: unknown;
  readonly bytes_hex?: string;
  readonly hash?: string;
}

interface Fixture {
  readonly protocol: string;
  readonly cases: readonly FixtureCase[];
  readonly errors: readonly FixtureCase[];
  readonly manifests: ReadonlyArray<{ readonly files: readonly ManifestFile[]; readonly hash: string }>;
}

const fixture = fixtureJson as unknown as Fixture;

function decodeFloat(raw: string): number | CanonicalFloat {
  const named: Record<string, number> = { nan: Number.NaN, inf: Infinity, '-inf': -Infinity };
  const value = named[raw] ?? Number(raw);
  return Number.isInteger(value) || Object.is(value, -0) ? new CanonicalFloat(value) : value;
}

function decodeInt(raw: string): number | bigint {
  const value = BigInt(raw);
  const safe = value <= BigInt(Number.MAX_SAFE_INTEGER) && value >= BigInt(Number.MIN_SAFE_INTEGER);
  return safe ? Number(value) : value;
}

function decodeTag(tag: string, raw: string): CanonicalValue {
  if (tag === '$int') return decodeInt(raw);
  if (tag === '$float') return decodeFloat(raw);
  if (tag === '$utf16') return String.fromCharCode(...raw.split(' ').map((unit) => parseInt(unit, 16)));
  return Uint8Array.from(atob(raw), (c) => c.charCodeAt(0));
}

function decode(node: unknown): CanonicalValue {
  if (Array.isArray(node)) return node.map(decode);
  if (node === null || typeof node !== 'object') return node as CanonicalValue;
  const entries = Object.entries(node);
  const [only] = entries;
  if (entries.length === 1 && only && ['$int', '$float', '$bytes', '$utf16'].includes(only[0])) {
    return decodeTag(only[0], String(only[1]));
  }
  return Object.fromEntries(entries.map(([k, v]) => [k, decode(v)]));
}

function hex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

describe('@amc/canonical parity with the Python reference', () => {
  it('uses the fixture protocol', () => {
    expect(fixture.protocol).toBe('AMC-CANON-1');
    expect(fixture.cases.length).toBeGreaterThan(500);
  });

  it('reproduces every fixture case byte-for-byte', async () => {
    for (const c of fixture.cases) {
      const value = decode(c.input);
      expect(hex(canonicalBytes(value)), c.name).toBe(c.bytes_hex);
      expect(await canonicalHash(value), c.name).toBe(c.hash);
    }
  });

  it('rejects every input Python rejects', () => {
    for (const c of fixture.errors) {
      expect(() => canonicalBytes(decode(c.input)), c.name).toThrow(CanonicalizationError);
    }
  });

  it('reproduces multi-file manifest hashes', async () => {
    for (const m of fixture.manifests) expect(await hashMultifileManifest(m.files)).toBe(m.hash);
  });
});

describe('@amc/canonical TypeScript-only rules', () => {
  it('encodes Map like a plain object and refuses non-string keys', () => {
    const map = new Map<string, CanonicalValue>([['b', 1], ['a', 2]]);
    expect(hex(canonicalBytes(map))).toBe(hex(canonicalBytes({ a: 2, b: 1 })));
    const bad = new Map<unknown, CanonicalValue>([[1, 'x']]) as unknown as CanonicalValue;
    expect(() => canonicalBytes(bad)).toThrow(CanonicalizationError);
  });

  it('refuses ambiguous or unsupported values instead of guessing', () => {
    expect(() => canonicalBytes(2 ** 60)).toThrow(/bigint/);
    expect(() => canonicalBytes(new Date(0) as unknown as CanonicalValue)).toThrow(CanonicalizationError);
    expect(() => canonicalBytes(undefined as unknown as CanonicalValue)).toThrow(CanonicalizationError);
    expect(() => canonicalBytes({ a: undefined } as unknown as CanonicalValue)).toThrow(CanonicalizationError);
  });

  it('keeps int and integral float distinct', () => {
    expect(hex(canonicalBytes(2))).not.toBe(hex(canonicalBytes(new CanonicalFloat(2))));
    expect(decimalText(1e21)).toBe('1000000000000000000000');
    expect(decimalText(-1.5e-7)).toBe('-0.00000015');
  });
});
